INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.chamring', $ck${"title": "CHAMRING code key – chamfering holders and inserts", "subtitle": "Drill holders for drilling and chamfering (30°, 45°, 60°) in one operation, for 7.5 – 25.9 mm drills, and their XCGT inserts", "example": "CHAMRING 080-WN20-06", "decoder": "chamring", "sections": [{"key": "t-family", "title": "Holder – family", "sample": "CHAMRING", "rows": [{"code": "CHAMRING", "meaning": "Drill holder for drilling and chamfering in one operation"}]}, {"key": "t-dia", "title": "Holder – drill size", "rows": [{"code": "###", "meaning": "Smallest drill diameter it holds x10 (e.g. 080 = 8.0 mm)"}]}, {"key": "t-height", "title": "Holder – shank", "rows": [{"code": "WN##", "meaning": "WN shank diameter in mm (20, 32)"}]}, {"key": "t-insert", "title": "Holder – insert size", "rows": [{"code": "##", "meaning": "Size of the XCGT inserts (06, 09)"}]}, {"key": "i-family", "title": "Insert – family", "sample": "XCGT", "rows": [{"code": "XCGT", "meaning": "Chamfering inserts for CHAMRING holders"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "######", "meaning": "Insert size code (060300, 090300)"}]}, {"key": "i-angle", "title": "Insert – chamfer angle", "rows": [{"code": "##", "meaning": "Chamfer angle in degrees (30, 45, 60)"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "DT", "meaning": "General use chipformer"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
